effect.shader:
const vec3 LUMA = vec3(0.2126, 0.7152, 0.0722);

// "fibonacci spiral" — amostras bem distribuídas num disco.
void main() {
    if (radius <= 0.0) { fragColor = texture(inputImg, acScreenNorm); return; }
    int n = clamp(int(samples), 6, 64);
    float phi = 2.39996323;

    vec4 soma = vec4(0.0);
    float pesoTot = 0.0;
    for (int i = 0; i <= 64; i++) {
        if (i > n) break;
        float t = float(i) / float(n);
        float r = sqrt(t) * radius;
        float a = float(i) * phi;
        vec2 off = vec2(cos(a), sin(a)) * r;
        off.x /= acAspect;
        vec4 c = texture(inputImg, acScreenNorm + off);
        float luz = dot(c.rgb, LUMA);
        float k = smoothstep(threshold, threshold + 0.2, luz);
        c.rgb *= (1.0 + highlight * k);
        soma += c;
        pesoTot += 1.0;
    }
    fragColor = soma / pesoTot;
}
